const COLORS = {
  'User Story':     '#0038FF',
  'Technical Task': '#1FD7C1',
  'Bug Report':     '#FF3D00',
};

/**
 * Returns an RFC4122 v4 UUID, falling back to Math.random when the
 * Web Crypto API is unavailable in the sandbox.
 * @returns {string} The generated UUID
 */
const uuid = () => (globalThis.crypto?.randomUUID)
  ? globalThis.crypto.randomUUID()
  : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
      const r = Math.random() * 16 | 0;
      return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });

/**
 * Trims a sender name down to a usable display name.
 * Cuts everything after the first separator and keeps at most three words,
 * so signatures and job titles do not end up on the board.
 * @param {string} raw - The name as extracted by the AI agent
 * @returns {string} The cleaned name, or 'Unbekannt' if nothing usable remains
 */
const cleanName = (raw) => {
  const first = String(raw ?? '').split(/[\n,|/]/)[0].trim();
  const words = first.split(/\s+/).slice(0, 3).join(' ');
  return words || 'Unbekannt';
};

/**
 * Extracts the bare address from an RFC 5322 From header.
 * Turns 'Ferri Ferrari <ferri@example.com>' into 'ferri@example.com' and
 * passes through headers that already contain only an address.
 * @param {string} raw - The From header of the incoming mail
 * @returns {string} The email address
 */
const parseEmail = (raw) => {
  const from = String(raw ?? '');
  return (from.match(/<([^>]+)>/)?.[1] ?? from).trim();
};

// Die Absenderadresse kommt aus dem Trigger, nicht vom Agent: sie steht im
// Header und soll nicht durch die KI laufen. Sie ist der Empfaenger der
// Benachrichtigung, wenn der Task spaeter verschoben wird.
const mails = $('Email Trigger (IMAP)').all();

return items.map((item, index) => {
  const out = item.json.output;
  const mail = (mails[index] ?? mails[0])?.json ?? {};

  return {
    json: {
      id: `task-${uuid()}`,
      title: String(out.title ?? '').slice(0, 60),
      description: out.description,
      category: out.category,
      categoryLabelColor: COLORS[out.category] ?? '#8A8A8A',
      dueDate: out.dueDate || DateTime.now().plus({ days: 30 }).toFormat('yyyy-MM-dd'),
      priority: out.priority,
      status: 'triage',
      assignedTo: (out.assignedTo ?? []).filter(
        a => typeof a?.id === 'string' && a.id.startsWith('contact-')
      ),
      creator: {
        type: 'extern',
        source: 'email',
        name: cleanName(out.creator?.name),
        email: parseEmail(mail.from)
      },
      subtasks: (out.subtasks ?? []).map(s => ({
        id: `subtask-${uuid()}`,
        title: s.title,
        completed: false
      })),
      aiGenerated: true
    }
  };
});

/**
 * Prüft, wie viele Slots des Tageslimits bereits verbraucht sind.
 *
 * Erwartet als Eingabe den heutigen Knoten aus /triggerCounter, also
 * GET /triggerCounter/<yyyy-MM-dd>.json?shallow=true. Mit shallow=true
 * liefert Firebase nur die Push-IDs als { "-Nxyz": true, ... } — genau das,
 * was zum Zählen gebraucht wird, ohne die Nutzdaten zu übertragen.
 *
 * @returns {Array<{json: {date: string, count: number, limit: number, remaining: number}}>}
 */
const LIMIT = 10;

const raw = $input.first().json ?? {};

const entries = 'data' in raw && raw.data === null ? {} : raw;

const count = Object.keys(entries).length;

return [{
  json: {
    date: $today.toFormat('yyyy-MM-dd'),
    count,
    limit: LIMIT,
    remaining: Math.max(LIMIT - count, 0),
  },
}];

parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "status": { "type": "string", "enum": ["ok", "rejected"] },
    "rejectionReason": {
      "type": "string",
      "description": "Short reason in English, one full sentence addressed to the sender. Inserted verbatim into an email."
    },
    "title": { "type": "string" },
    "description": { "type": "string" },
    "category": {
      "type": "string",
      "enum": ["User Story", "Technical Task", "Bug Report"]
    },
    "dueDate": { "type": "string" },
    "priority": { "type": "string", "enum": ["low", "medium", "urgent"] },
    "subtasks": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": { "title": { "type": "string" } },
        "required": ["title"]
      }
    },
    "creator": {
      "type": "object",
      "properties": { "name": { "type": "string" } },
      "required": ["name"]
    },
    "assignedTo": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": { "id": { "type": "string" } },
        "required": ["id"]
      }
    }
  },
  "required": ["status"]
}
